        return oracle_cache[cipher]

    for _ in range(3):  # Try 3 times
        try:
            conn = remote('crypto.chal.csaw.io', 5000, level='error')
            conn.recvuntil(b'Choice: ')
            conn.sendline(b'3')
            conn.recvuntil(b'Give me a ciphertext to decrypt: ')
            conn.sendline(str(cipher).encode())
            result = int(conn.recvline().strip().decode())
            conn.close()
            oracle_cache[cipher] = result
            return result
        except:
            time.sleep(1)
            continue
    return None

def attack_block(start_bit, bits=32):
    lower = gmpy2.mpz(0)
    upper = gmpy2.mpz(N)
    multiplier = pow(2, e, N)

    print(f"Attacking bits {start_bit} to {start_bit + bits}")

    for i in range(bits):
        current_bit = start_bit + i
        print(f"Bit {current_bit}", end='\r')
        test_c = (c * pow(multiplier, current_bit, N)) % N

        bit = oracle(test_c)
        if bit is None:
            print(f"\nFailed at bit {current_bit}")
            return lower, False

        if bit == 1:
            lower = lower + (N >> (current_bit + 1))
        upper = lower + (N >> (current_bit + 1))

        # Try to decode periodically
        if current_bit > 32 and current_bit % 8 == 0:
            try:
                partial = long_to_bytes(int(lower))
                print(f"\nPartial ({current_bit} bits): {partial}")
                if b'flag{' in partial:
                    return lower, True
            except:
                pass

    return lower, True

def main():
    # Attack in smaller blocks to handle timeouts better
    block_size = 32
    total_bits = 96  # Should be enough for the flag
    current_lower = 0

    for start_bit in range(0, total_bits, block_size):
        lower, success = attack_block(start_bit, min(block_size, total_bits - start_bit))
        if success:
            current_lower = lower
            try:
