from pwn import *
import gmpy2
from Crypto.Util.number import *
import time
import sys

# Challenge parameters
N = 
e = 65537
c = 

def oracle(cipher, retries=3, base_delay=1):
    for attempt in range(retries):
        try:
            conn = remote('crypto.chal.csaw.io', 5000, level='error')
            conn.recvuntil(b'Choice: ')
            conn.sendline(b'3')
            conn.recvuntil(b'Give me a ciphertext to decrypt: ')
            conn.sendline(str(cipher).encode())
            result = int(conn.recvline().strip().decode())
            conn.close()
            return result
        except Exception as e:
            delay = base_delay * (2 ** attempt)
            time.sleep(delay)
            continue
    return None

class LSBOracle:
    def __init__(self):
        self.lower = gmpy2.mpz(0)
        self.upper = gmpy2.mpz(N)
        self.multiplier = pow(2, e, N)
        self.cache = {}

    def get_bit(self, i):
        test_c = (c * pow(self.multiplier, i, N)) % N

        # Check cache
        if test_c in self.cache:
            return self.cache[test_c]

        bit = oracle(test_c)
        if bit is not None:
            self.cache[test_c] = bit
        return bit

    def attack(self):
        print("Starting LSB oracle attack...")
        sys.stdout.flush()

        for i in range(40):  # Try to get enough bits for flag{
            print(f"Bit {i}")
            sys.stdout.flush()

            bit = self.get_bit(i)
            if bit is None:
                print(f"Failed at bit {i}, trying to recover...")
                sys.stdout.flush()
                break

            if bit == 1:
                self.lower = self.lower + (N >> (i + 1))
            self.upper = self.lower + (N >> (i + 1))

            # Try to find flag pattern every few bits
            if i >= 32:
                try:
                    partial = long_to_bytes(int(self.lower))
                    print(f"Partial ({i} bits): {partial}")
                    sys.stdout.flush()
                    if b'flag{' in partial:
                        return partial
                except:
                    continue

        # Return final attempt
        try:
            return long_to_bytes(int(self.lower))
        except:
            return None

def main():
    oracle_attack = LSBOracle()
    result = oracle_attack.attack()
    if result:
        print(f"Final result: {result}")
    else:
        print("Attack failed")

if __name__ == '__main__':
    main()
